package com.bbx_audio.crateapp

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.webkit.WebView
import androidx.activity.OnBackPressedCallback
import androidx.activity.enableEdgeToEdge
import androidx.core.app.ActivityCompat
import androidx.core.content.ContextCompat

/**
 * The app activity, extending the Tauri-generated [TauriActivity] with Android-specific behavior
 * (#62). The `generated/` sources are regenerated by the Tauri CLI and must never be edited —
 * everything custom lives here:
 *
 * - **Share intake**: `ACTION_SEND` text shares (manifest intent-filter) are queued in
 *   [ShareIntentQueue] — cold start (`onCreate`, long before the webview exists) and warm
 *   (`onNewIntent`, `launchMode="singleTask"`) both funnel through [consumeShareIntent]; the
 *   frontend drains the queue via the `take_shared_texts` command.
 * - **Hardware Back**: an always-enabled [OnBackPressedCallback] asks the frontend
 *   (`window.__CRATE_BACK__`, see apps/mobile/src/lib/androidBack.ts) whether it consumed the
 *   press; `"true"` means a surface closed / navigation popped, anything else (including a JS
 *   error) backgrounds the app via `moveTaskToBack` — fail-safe, the user is never trapped.
 * - **Background playback keep-alive**: `WryActivity.onPause()` suspends the WebView, which
 *   would silence HTML5 preview audio the moment the app backgrounds — while playback is active
 *   ([CrateMediaService.isPlaybackActive]), the WebView is resumed right back so audio continues
 *   under the foreground service; an idle backgrounded app keeps the battery win of a paused
 *   WebView.
 */
class MainActivity : TauriActivity() {
  private var webView: WebView? = null

  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
    registerBackCallback()
    requestNotificationPermission()
    // Cold-start share; skip on activity recreation (rotation/theme), which re-delivers the
    // original intent that was already consumed.
    if (savedInstanceState == null) consumeShareIntent(intent)
  }

  override fun onNewIntent(intent: Intent) {
    // Load-bearing: TauriActivity forwards to the PluginManager — dropping it breaks the
    // web-auth plugin's OAuth Custom Tabs redirect.
    super.onNewIntent(intent)
    consumeShareIntent(intent)
  }

  override fun onWebViewCreate(webView: WebView) {
    this.webView = webView
  }

  override fun onPause() {
    super.onPause() // WryActivity pauses the WebView here
    if (CrateMediaService.isPlaybackActive) webView?.onResume()
  }

  private fun consumeShareIntent(intent: Intent?) {
    if (intent?.action != Intent.ACTION_SEND || intent.type?.startsWith("text/") != true) return
    // Relaunching from recents re-delivers the original share intent — don't re-add it.
    if (intent.flags and Intent.FLAG_ACTIVITY_LAUNCHED_FROM_HISTORY != 0) return
    val text = intent.getStringExtra(Intent.EXTRA_TEXT) ?: return
    ShareIntentQueue.enqueue(text)
    // Warm-share nudge so a running frontend drains immediately (no-op pre-boot — the cold-start
    // path is covered by the frontend's drain-on-init).
    webView?.post {
      webView?.evaluateJavascript("window.dispatchEvent(new Event('crate-android-share'))", null)
    }
  }

  private fun registerBackCallback() {
    // Always enabled: the per-press handled/unhandled decision lives in the frontend (its state
    // is synchronous), and `TauriActivity.handleBackNavigation = false` means no competing wry
    // callback. evaluateJavascript's completion value is the verdict.
    onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
      override fun handleOnBackPressed() {
        val view = webView
        if (view == null) {
          moveTaskToBack(true)
          return
        }
        view.evaluateJavascript("window.__CRATE_BACK__ ? window.__CRATE_BACK__() : false") { result ->
          if (result != "true") moveTaskToBack(true)
        }
      }
    })
  }

  private fun requestNotificationPermission() {
    // The playback foreground service posts a MediaStyle notification; on API 33+ it stays
    // hidden without POST_NOTIFICATIONS (the service itself still runs). Asking at launch is the
    // common media-app pattern; a denial is honored silently (Android suppresses re-prompts).
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return
    val granted = ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS) ==
      PackageManager.PERMISSION_GRANTED
    if (!granted) {
      ActivityCompat.requestPermissions(this, arrayOf(Manifest.permission.POST_NOTIFICATIONS), 1)
    }
  }
}
